<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\UserInvitation\Application\Usecase\Create;

use DateTimeImmutable;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitation;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitationAttributes;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitationStatusOptions;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\Gateway\UserInvitationWriteGateway;
use Civi\Lughauth\Features\Oidc\UserInvitation\Domain\Gateway\UserInvitationQueryGateway;
use Civi\Lughauth\Features\Oidc\UserInvitation\Domain\Gateway\UserInvitationMailGateway;

class InvitationCreateUsecase
{
    public function __construct(
        private readonly UserInvitationWriteGateway $writeGateway,
        private readonly UserInvitationQueryGateway $queryGateway,
        private readonly UserInvitationMailGateway $mailer,
    ) {
    }

    public function create(InvitationCreateParams $params): InvitationCreateResult
    {
        $existing = $this->queryGateway->findPendingByEmail($params->email, $params->tenantId);
        if ($existing !== null && $existing->getExpiredAt() > new DateTimeImmutable()) {
            throw new \DomainException('There is already a pending invitation for this email.');
        }

        $rawToken  = bin2hex(random_bytes(32));
        $tokenHash = hash('sha256', $rawToken);
        $expiresAt = new DateTimeImmutable('+7 days');

        $attrs = new UserInvitationAttributes();
        $attrs->uid(Random::comb());
        $attrs->tenant(new TenantRef($params->tenantId));
        $attrs->email($params->email);
        $attrs->invitedBy(new UserRef($params->invitedByUserUid));
        $attrs->tokenHash($tokenHash);
        $attrs->status(UserInvitationStatusOptions::PENDING);
        $attrs->createdAt(new DateTimeImmutable());
        $attrs->expiredAt($expiresAt);
        if ($params->roles !== null) {
            $attrs->roles($params->roles);
        }
        if ($params->metadataJson !== null) {
            $attrs->metadataJson($params->metadataJson);
        }

        $invitation = $this->writeGateway->create(UserInvitation::create($attrs));

        $acceptUrl = rtrim($params->baseUrl, '/') . '/oauth/openid/' . urlencode($params->tenantName)
            . '/invitation/accept?token=' . urlencode($rawToken);

        $this->mailer->sendInvitation(
            toEmail: $params->email,
            tenant: new TenantRef($params->tenantId),
            acceptUrl: $acceptUrl,
            invitedByEmail: $params->invitedByEmail,
            expiresAt: $expiresAt,
        );

        return new InvitationCreateResult(
            uid: $invitation->uid() ?? '',
            expiresAt: $expiresAt,
        );
    }
}
